    }
    let keys: std::collections::BTreeSet<&String> =
        reference.fields.keys().chain(derived.fields.keys()).collect();
    for k in keys {
        match (reference.fields.get(k), derived.fields.get(k)) {
            (Some(r), Some(v)) => {
                if type_tag(&r.field_type) != type_tag(&v.field_type) {
                    d.push(format!("{k}.type: {} -> {}", type_tag(&r.field_type), type_tag(&v.field_type)));
                }
                if r.required != v.required {
                    d.push(format!("{k}.required: {} -> {}", r.required, v.required));
                }
                if r.description != v.description {
